DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_invoice_asset_source(uuid,uuid)'::regprocedure) INTO def;def:=replace(def,'''line'',to_jsonb(l),''invoice'',to_jsonb(i)', '''line'',to_jsonb(l),''invoice'',to_jsonb(i),''all_lines'',(SELECT jsonb_agg(to_jsonb(sibling) ORDER BY sibling.id) FROM invoice_line_items sibling WHERE sibling.tenant_id=t AND sibling.invoice_id=i.id)');EXECUTE def;
SELECT pg_get_functiondef('public.finance_sales_deferred_edit(uuid,jsonb)'::regprocedure) INTO def;def:=replace(def,'PERFORM finance_assert_open(t,s.date::date);','IF (SELECT count(*) FROM sales_records WHERE tenant_id=t AND date=s.date AND venue=s.venue)>1 THEN RAISE EXCEPTION ''Combined sales requires a grouped correction'';END IF;PERFORM finance_assert_open(t,s.date::date);');EXECUTE def;END $$;